local CardProgressionEquipmentExchangeNode = Class("CardProgressionEquipmentExchangeNode")

--region lifecycle
function CardProgressionEquipmentExchangeNode:__init()
    self._selectedCardId = nil
    self._exchangeListData = {}
    self._selectedIdx = nil
end

function CardProgressionEquipmentExchangeNode:__delete()
    self._selectedCardId = nil
    self._exchangeListData = nil
    self._selectedIdx = nil
end

function CardProgressionEquipmentExchangeNode:Awake()
    self:InitHandler()
end

function CardProgressionEquipmentExchangeNode:Start()

end

function CardProgressionEquipmentExchangeNode:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
--endregion lifecycle

--region init
function CardProgressionEquipmentExchangeNode:InitHandler()
    SetButtonAction(self.FontStyleButton1, Bind(self, self.BtnCancelOnClickHandler))
    SetButtonAction(self.FontStyleButton2, Bind(self, self.BtnExchangeOnClickHandler))
end
--endregion init

--region handler
---取消按钮点击处理
function CardProgressionEquipmentExchangeNode:BtnCancelOnClickHandler()
    if not self._cancelBtnCallback then return end
    self._cancelBtnCallback()
end

---交换按钮点击处理
function CardProgressionEquipmentExchangeNode:BtnExchangeOnClickHandler()
    if next(self._exchangeListData) == nil then return end
    if not self._selectedIdx then
        GameUtils.Toast(localize("请选择需要交换的角色"))
        return 
    end
    if not self._exchangeBtnCallback then return end
    self._exchangeBtnCallback(self._exchangeListData[self._selectedIdx].id)
end

---cell点击处理
function CardProgressionEquipmentExchangeNode:CellOnClickHandler(index)
    if not self._cellClickCallback then return end
    self._cellClickCallback(index)
end

---OnGetItemByIndex
---@param idx number
function CardProgressionEquipmentExchangeNode:OnGetItemByIndex(listView, idx)
    if idx < 0 then return nil end

    local cell = listView:NewListViewItem("CellSuit")
    local nodeEnv = CfUtils.GetLuaScr(cell, "Game.CardProgression.Equip.CardProgressionEquipmentExchangeListCell")
    if isNull(nodeEnv) then
        return
    end
    local index = idx + 1
    local data = self._exchangeListData[index]
    if not nodeEnv:GetOnClickCallback() then
        nodeEnv:SetOnClickCallback(Bind(self, self.CellOnClickHandler))
    end
    nodeEnv:RefreshCell(data, index)

    if index == self._selectedIdx then
        nodeEnv:PlaySelectAnimation()
    else
        nodeEnv:PlayDefaultAnimation()
    end
    
    return cell
end
--endregion handler

--region public
---刷新UI
---@param selectedCardId integer 选中的卡牌id
function CardProgressionEquipmentExchangeNode:RefreshUI(selectedCardId)
    self._selectedCardId = checkInt(selectedCardId)
    self._exchangeListData = self:ConvertExchangeListData(selectedCardId)
    self:RefreshScrollView()
end

---设置返回按钮点击回调
function CardProgressionEquipmentExchangeNode:SetCancelBtnCallback(callback)
    self._cancelBtnCallback = callback
end

---设置交换按钮点击回调
function CardProgressionEquipmentExchangeNode:SetExchangeBtnCallback(callback)
    self._exchangeBtnCallback = callback
end

---设置cell点击回调
function CardProgressionEquipmentExchangeNode:SetCellClickCallback(callback)
    self._cellClickCallback = callback
end

---设置selectedIndex
function CardProgressionEquipmentExchangeNode:ClearSelectedIndex()
    self._selectedIdx = nil
end

---选中cell
function CardProgressionEquipmentExchangeNode:SelectCell(index)
    local preIndex = self._selectedIdx
    self._selectedIdx = index
    local cell = self.LoopListSuit:GetShownItemByItemIndex(index - 1)
    if isNull(cell) then return end
    
    local env = CfUtils.GetLuaScr(cell, "Game.CardProgression.Equip.CardProgressionEquipmentExchangeListCell")
    if isNull(env) then return end
    
    env:PlaySelectAnimation()
    
    if not preIndex then return end
    local preCell = self.LoopListSuit:GetShownItemByItemIndex(preIndex - 1)
    if isNull(cell) then return end

    local preEnv = CfUtils.GetLuaScr(preCell, "Game.CardProgression.Equip.CardProgressionEquipmentExchangeListCell")
    if isNull(preEnv) then return end

    preEnv:PlayUnselectAnimation()
end
--endregion public

--region private
---转换交换列表数据
---@param excludeCardId integer 排除的卡牌id
function CardProgressionEquipmentExchangeNode:ConvertExchangeListData(excludeCardId)
    ---@type CardComponent
    local cardComp           = CardProgressionMgr:GetCardComp()
    ---@type CardDojo
    local cards              = cardComp:GetAllCardTable()
    local exchangeListData = {}
    for _, v in ipairs(cards) do
        if checkInt(v.cardId) ~= excludeCardId then
            local hasEquipment = false
            for i = 1, CardProgressionConstants.EquipmentNum do
                if checkInt(v[string.format('equipment%d', i)]) ~= 0 then
                    hasEquipment = true
                    break
                end
            end
            if hasEquipment then
                table.insert(exchangeListData, v)
            end
        end
    end
    return exchangeListData
end

---RefreshScrollView
---@param result table
function CardProgressionEquipmentExchangeNode:RefreshScrollView()
    local count = #self._exchangeListData
    local isShowList = count > 0
    KTool.SetActive(self.LoopListSuit.gameObject, isShowList)
    if isShowList then
        CfUtils.SetActive(self.EmptyNode, false)
        local List = self.LoopListSuit  
        if not List.IsListViewInit then
            List:InitGridView(count, Bind(self, self.OnGetItemByIndex))
        else
            GameUtils.ReloadData(List, count)
            List:MovePanelToItemByIndex(0)
        end
    else
        -- 列表为空的状态
        CfUtils.SetActive(self.EmptyNode, true)
    end
    return isShowList
end


--endregion private

return CardProgressionEquipmentExchangeNode